/**
 * Client runtime: Swup page transitions, scroll reveal, and header state.
 *
 * - Scroll reveal for `[data-reveal]` elements (`[data-reveal-watch]` elements
 *   are observed but never hidden; used by the footer to start its wordmark).
 * - Keeps the header's `aria-current` correct after client-side navigation.
 */
import Swup from "swup";
import HeadPlugin from "@swup/head-plugin";

const root = document.documentElement;
const REVEAL_SELECTOR = "[data-reveal]";
const WATCH_SELECTOR = "[data-reveal], [data-reveal-watch]";

let observer: IntersectionObserver | null = null;

const motionEnabled = () =>
  "IntersectionObserver" in window &&
  !window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function bindReveal() {
  observer?.disconnect();
  observer = null;

  if (!motionEnabled()) {
    root.classList.remove("reveal-ready");
    document.querySelectorAll(WATCH_SELECTOR).forEach((el) => el.classList.add("is-visible"));
    return;
  }

  root.classList.add("reveal-ready");

  observer = new IntersectionObserver(
    (entries) => {
      let index = 0;
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        const el = entry.target as HTMLElement;
        if (el.matches(REVEAL_SELECTOR)) {
          // Items entering together cascade, capped at 300ms.
          el.style.setProperty("--reveal-delay", `${Math.min(index, 6) * 50}ms`);
          index += 1;
        }
        el.classList.add("is-visible");
        observer?.unobserve(el);
      }
    },
    { threshold: 0.12, rootMargin: "0px 0px -8% 0px" },
  );

  document.querySelectorAll(WATCH_SELECTOR).forEach((el) => {
    if (!el.classList.contains("is-visible")) observer?.observe(el);
  });
}

function updateAriaCurrent() {
  const path = location.pathname.replace(/\/+$/, "") || "/";
  document.querySelectorAll<HTMLAnchorElement>(".site-head-nav a[data-section]").forEach((link) => {
    const sections = (link.dataset.section ?? "").split(/\s+/).filter(Boolean);
    const current = sections.some((section) => path === section || path.startsWith(`${section}/`));
    if (current) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
}

const swup = new Swup({
  containers: ["#swup"],
  cache: true,
  animationSelector: "[class*='transition-']",
  plugins: [new HeadPlugin()],
});

swup.hooks.on("page:view", () => {
  bindReveal();
  updateAriaCurrent();
});

bindReveal();
updateAriaCurrent();
name: PR Screenshots

on:
  pull_request:
    types: [opened, synchronize, reopened]

permissions:
  contents: read
  pull-requests: write

concurrency:
  group: pr-screenshots-${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  screenshots:
    runs-on: ubuntu-latest
    timeout-minutes: 15

    steps:
      - name: Acknowledge PR
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: [
                '## Screenshot Preview',
                '',
                'Taking full-page screenshots of all pages at **desktop (1440px)** and **mobile (390px)** viewports.',
                '',
                'This will produce:',
                '- Full-page desktop screenshots of every page',
                '- Full-page mobile screenshots of every page',
                '- Downloadable artifact with all images',
                '',
                'Results will be posted here when complete.',
                '',
                `_Triggered by commit \`${context.sha.substring(0, 7)}\`_`
              ].join('\n')
            });

      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - name: Build site
        run: npm run build:astro
        env:
          SITE_URL: http://localhost:4321

      - name: Discover all pages
        run: node scripts/ci/discover-pages.mjs --format=json > /tmp/pages.json

      - name: Log discovered pages
        run: |
          echo "Discovered $(node -e "console.log(JSON.parse(require('fs').readFileSync('/tmp/pages.json','utf8')).length)") pages"
          cat /tmp/pages.json

      - name: Install Playwright
        run: npx -y playwright install chromium --with-deps

      - name: Start preview server
        run: npx astro preview --host 0.0.0.0 &
        env:
          SITE_URL: http://localhost:4321

      - name: Wait for server
        run: |
          for i in $(seq 1 30); do
            if curl -s http://localhost:4321/ > /dev/null 2>&1; then
              echo "Server ready"
              break
            fi
            echo "Waiting for server... ($i)"
            sleep 1
          done

      - name: Capture screenshots
        run: node scripts/ci/capture-screenshots.mjs --pages=/tmp/pages.json --output=screenshots/

      - name: Upload screenshots
        uses: actions/upload-artifact@v4
        with:
          name: pr-screenshots-${{ github.event.pull_request.number }}
          path: screenshots/
          retention-days: 30

      - name: Comment with results
        if: always()
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');

            let pages = [];
            try {
              pages = JSON.parse(fs.readFileSync('/tmp/pages.json', 'utf8'));
            } catch {}

            const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

            let desktopCount = 0;
            let mobileCount = 0;
            try {
              desktopCount = fs.readdirSync('screenshots/desktop').filter(f => f.endsWith('.png')).length;
            } catch {}
            try {
              mobileCount = fs.readdirSync('screenshots/mobile').filter(f => f.endsWith('.png')).length;
            } catch {}

            const total = desktopCount + mobileCount;

            if (total === 0) {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: [
                  '## Screenshot Results',
                  '',
                  'No screenshots were captured. Check the [workflow run](' + runUrl + ') for errors.',
                  '',
                  'cc @manikrathee'
                ].join('\n')
              });
              return;
            }

            const body = [
              '## Screenshot Results',
              '',
              `**${pages.length} pages** captured at 2 viewports = **${total} screenshots**`,
              '',
              `| Viewport | Size | Count |`,
name: PR Screen Recordings

on:
  pull_request:
    types: [opened, synchronize, reopened]

permissions:
  contents: read
  pull-requests: write

concurrency:
  group: pr-recordings-${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  recordings:
    runs-on: ubuntu-latest
    timeout-minutes: 12

    steps:
      - name: Acknowledge PR
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: [
                '## Screen Recording Preview',
                '',
                'Creating screen recordings of affected pages showing:',
                '- Page load animation',
                '- Scroll behavior and lazy image loading',
                '- Quick hover interaction on nav and post cards',
                '',
                'Analyzing changed files to determine affected pages...',
                '',
                `_Triggered by commit \`${context.sha.substring(0, 7)}\`_`
              ].join('\n')
            });

      - uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - run: npm ci

      - name: Build site
        run: npm run build:astro
        env:
          SITE_URL: http://localhost:4321

      - name: Discover all pages
        run: node scripts/ci/discover-pages.mjs --format=json > /tmp/pages.json

      - name: Get changed files
        run: |
          git diff --name-only origin/master...HEAD > /tmp/changed-files.txt || \
            git diff --name-only HEAD~1 > /tmp/changed-files.txt
          echo "Changed files:"
          cat /tmp/changed-files.txt

      - name: Map changes to routes
        run: |
          node scripts/ci/map-changes-to-routes.mjs \
            --changes=/tmp/changed-files.txt \
            --pages=/tmp/pages.json \
            --max=2 \
            > /tmp/affected-routes.json
          echo "Affected routes:"
          cat /tmp/affected-routes.json

      - name: Install Playwright
        run: npx -y playwright install chromium --with-deps

      - name: Start preview server
        run: npx astro preview --host 0.0.0.0 &
        env:
          SITE_URL: http://localhost:4321

      - name: Wait for server
        run: |
          for i in $(seq 1 30); do
            if curl -s http://localhost:4321/ > /dev/null 2>&1; then
              echo "Server ready"
              break
            fi
            echo "Waiting for server... ($i)"
            sleep 1
          done

      - name: Capture recordings
        run: node scripts/ci/capture-recordings.mjs --routes=/tmp/affected-routes.json --output=recordings/

